  describe() { return this.title; }
}
class DigitalProduct extends Product {
  download() { return 'link'; }
}

const samples = {
  'Object literal': { id: 1, name: 'Anu' },
  'Array': ['pen', 'bag'],
  'DigitalProduct': new DigitalProduct('JS course'),
  'Object.create(null)': Object.assign(Object.create(null), { a: 1 }),
  'Function': function total() {},
};
let current = 'DigitalProduct';

function labelFor(obj, isTarget) {
  if (isTarget) return 'your value';
  const ctor = Object.hasOwn(obj, 'constructor') ? obj.constructor : null;
  return ctor ? `${ctor.name}.prototype` : 'object';
}

function render() {
  const key = document.querySelector('#prop').value.trim();
  const list = document.querySelector('#chain');
  list.replaceChildren();
  let obj = samples[current];
  let depth = 0;
  let foundAt = -1;
  while (obj !== null) {
    const names = Reflect.ownKeys(obj).filter((k) => typeof k === 'string');
    const li = document.createElement('li');
    li.className = 'level';
    const title = document.createElement('div');
    title.className = 'name';
    title.textContent = `${depth}. ${labelFor(obj, depth === 0)}`;
    const keys = document.createElement('div');
    keys.className = 'keys';
    const shown = names.slice(0, 10);
    for (const n of shown) {
      const span = document.createElement('span');
      span.className = 'key' + (n === key ? ' match' : '');
      span.textContent = n;
      keys.append(span);
    }
    if (names.length > shown.length) {
      const more = document.createElement('span');
      more.className = 'key';
      more.textContent = `+${names.length - shown.length} more`;
      keys.append(more);
    }
    if (foundAt < 0 && key && Object.hasOwn(obj, key)) {
      foundAt = depth;
      li.classList.add('hit');
      if (!shown.includes(key)) {
        const span = document.createElement('span');
        span.className = 'key match';
        span.textContent = key;
        keys.prepend(span);
      }
    }
    li.append(title, keys);
    list.append(li);
    obj = Object.getPrototypeOf(obj);
    depth++;
  }
  const end = document.createElement('li');
  end.className = 'level end';
  end.textContent = 'null: the end of the chain';
  list.append(end);

  const result = document.querySelector('#result');
  result.replaceChildren();
  const b = document.createElement('b');
  b.textContent = key || '(empty)';
  result.append(b, foundAt < 0
    ? ' was not found: the lookup reached null, so the value is undefined.'
    : foundAt === 0 ? ' is an own property.'
    : ` is inherited: found ${foundAt} step(s) up the chain.`);
  document.querySelectorAll('.chip').forEach((c) =>
    c.setAttribute('aria-pressed', c.textContent === current));
}

document.querySelector('#pick').append(...Object.keys(samples).map((name) => {
  const btn = document.createElement('button');
  btn.className = 'chip';
  btn.textContent = name;
  btn.addEventListener('click', () => { current = name; render(); });
  return btn;
}));
document.querySelector('#prop').addEventListener('input', render);
